package com.franco.desco.adapter.in.web.visit;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.application.visit.*;import com.franco.desco.domain.visit.VisitModels;import org.springframework.stereotype.Component;import java.time.Instant;
@Component public class VisitWebMapper{public VisitCommands.ListVisits list(int p,int t,Long predio,Long empleado,Long salida,String estado,Instant desde,Instant hasta,String buscar){return new VisitCommands.ListVisits(new PageRequest<>(p,t,new VisitCommands.Filter(predio,empleado,salida,estado,desde,hasta,buscar),null,null));}public VisitResponses.Summary response(VisitModels.Summary x){return new VisitResponses.Summary(x.visitaTecnicaId(),x.salidaParticipanteId(),x.salidaCampoId(),x.empleadoId(),x.tecnico(),x.predioId(),x.codigoPredio(),x.predio(),x.fechaHoraInicio(),x.fechaHoraFin(),x.objetivo(),x.estadoProceso(),x.latitud(),x.longitud());}public VisitResponses.Detail response(VisitModels.Detail x){return new VisitResponses.Detail(response(x.visita()),x.resumen(),x.recomendaciones(),x.evaluaciones().stream().map(e->new VisitResponses.Evaluation(e.evaluacionAgronomicaId(),e.parcelaCultivoId(),e.tipoEvaluacionId(),e.codigoTipoEvaluacion(),e.tipoEvaluacion(),e.fechaHora(),e.resultado(),e.observacion(),e.porcentajeMateriaSeca(),e.numeroMuestras())).toList(),x.archivos().stream().map(f->new VisitResponses.File(f.archivoId(),f.nombreOriginal(),f.mimeType(),f.tamanoBytes(),f.secureUrl(),f.categoria(),f.origenCaptura(),f.fechaCarga())).toList());}}
